import"chrome://resources/cr_elements/cr_button/cr_button.js";import"./signin_shared.css.js";import"./strings.m.js";import{assert,assertNotReached}from"chrome://resources/js/assert.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{SyncConfirmationBrowserProxyImpl}from"./sync_confirmation_browser_proxy.js";import{getTemplate}from"./sync_disabled_confirmation_app.html.js";class SyncDisabledConfirmationAppElement extends PolymerElement{constructor(){super(...arguments);this.syncConfirmationBrowserProxy_=SyncConfirmationBrowserProxyImpl.getInstance()}static get is(){return"sync-disabled-confirmation-app"}static get template(){return getTemplate()}static get properties(){return{signoutDisallowed_:{type:Boolean,value(){return loadTimeData.getBoolean("signoutDisallowed")}}}}connectedCallback(){super.connectedCallback();document.addEventListener("keydown",(e=>this.onKeyDown_(e)))}onConfirm_(e){this.syncConfirmationBrowserProxy_.confirm(this.getConsentDescription_(),this.getConsentConfirmation_(e.composedPath()))}getConsentConfirmation_(path){for(const element of path){if(element.nodeType!==Node.DOCUMENT_FRAGMENT_NODE&&element.hasAttribute("consent-confirmation")){return element.innerHTML.trim()}}assertNotReached("No consent confirmation element found.")}getConsentDescription_(){const consentDescription=Array.from(this.shadowRoot.querySelectorAll("[consent-description]")).filter((element=>element.clientWidth*element.clientHeight>0)).map((element=>element.innerHTML.trim()));assert(consentDescription);return consentDescription}onKeyDown_(e){if(e.key==="Enter"&&!/^(A|PAPER-(BUTTON|CHECKBOX))$/.test(document.activeElement.tagName)){this.$.confirmButton.click();e.preventDefault()}}onUndo_(){this.syncConfirmationBrowserProxy_.undo()}}customElements.define(SyncDisabledConfirmationAppElement.is,SyncDisabledConfirmationAppElement);